/* ── Waybar base ───────────────────────────────────────────── */
* {
    font-family: "JetBrainsMono Nerd Font Propo", monospace;
    font-size: 15px;
    border: none;
    border-radius: 7;
    min-height: 0;
}

window#waybar {
    background-color: rgba(30, 30, 46, 1);
    color: #cdd6f4;
}

/* ── Tooltip ───────────────────────────────────────────────── */
tooltip {
    background-color: #1e1e2e;
    border: 1px solid #3a5456;
    color: #cdd6f4;
}

tooltip label {
    color: #cdd6f4;
}

/* ── Generic module wrapper ────────────────────────────────── */
.modules-left,
.modules-center,
.modules-right {
    padding: 0 2px;
}

/* ── Separator ─────────────────────────────────────────────── */
#custom-separator {
    color: #9399b2;
    padding: 0.5 0.5px;
}

#custom-pac {
  color: #94e2d5;
  padding: 1 2.5px;
}

#window {
    color: #f2cdcd;
    padding: 1 2.5px;
}

/* ── Clock ─────────────────────────────────────────────────── */
#clock {
    color: #f9e2af;
    padding: 1 2.5px;
}

/* ── CPU ────────────────────────────────────────────────────── */
#cpu {
    color: #f5c2e7;
    padding: 1 2.5px;
}

/* nerdfont icon inherits color — override to orange */
#cpu label:first-child {
    color: #ff966c;
}

/* ── Memory ─────────────────────────────────────────────────── */
#memory {
    color: #fab387;
    padding: 1 2.5px;
}

/* ── Temperature ────────────────────────────────────────────── */
#temperature {
    color: #f5c2e7;
    padding: 1 2.5px;
}

#temperature.critical {
    color: #f38ba8;
}

#disk {
    color: #fca7ea;
    padding: 1 2.5px;
}


/* ── Backlight ──────────────────────────────────────────────── */
#backlight {
    color: #89b4fa;
    padding: 1 2.5px;
}

/* ── Battery ────────────────────────────────────────────────── */
#battery {
    color: #a6e3a1;
    padding: 1 2.5px;
}

#battery.charging,
#battery.plugged {
    color: #a6e3a1;           /* soft green when charging */
}

#battery.warning:not(.charging) {
    color: #f38ba8;
}

#battery.critical:not(.charging) {
    color: #f38ba8;
    animation: blink 0.5s step-end infinite alternate;
}

@keyframes blink {
    to { color: transparent; }
}

/* ── Network ────────────────────────────────────────────────── */
#network {
    color: #89b4fa;
    padding: 1 2.5px;
}

#network.disconnected {
    color: #89b4fa;
}

/* ── Pulseaudio ─────────────────────────────────────────────── */
#pulseaudio {
    color: #89b4fa;
    padding: 1 2.5px;
}

#pulseaudio.muted {
  padding: 1 2.5px;
  color: #89b4fa;
}

#pulseaudio.microphone {
  padding: 1 2.5px;
  color: #89b4fa;
}

#pulseaudio.microphone#muted {
  padding: 1 2.5px;
  color: #89b4fa
}


/* ── Spotify ────────────────────────────────────────────────── */
#custom-spotify {
    color: #94e2d5;
    padding: 1 2.5px;
}

#custom-next {
  color: #94e2d5;
  padding: 1 4.5px;

}

#custom-before {
  color: #94e2d5;
  padding: 1 4.5px;

}

#custom-weather {
    color: #b4befe;
    padding: 1 2.5px;
